class ParkingTicket { private final long id; private final String vehicle; ParkingTicket(){this(0,"UNKNOWN");} ParkingTicket(long id){this(id,"UNKNOWN");} ParkingTicket(long id,String vehicle){this.id=id;this.vehicle=vehicle;} public String toString(){return "Ticket "+id+" for "+vehicle;} } public class Main { public static void main(String[]a){System.out.println(new ParkingTicket());System.out.println(new ParkingTicket(1001));System.out.println(new ParkingTicket(1002,"TN01AB1234"));} }
